        "decisions": [
          {
            "topic": "Orchestration ownership",
            "choice": "Board feature use-case",
            "rationale": "Archived filtering, grouping, label attachment, and cross-capability authorization are board policy, not work-item or label persistence concerns."
          },
          {
            "topic": "Dependency direction",
            "choice": "Use-case ports with composition in the server-only DAL",
            "rationale": "The use-case remains framework- and adapter-independent while the DAL/inbound composition root selects trusted capability implementations."
